insert into public.services
  (id, name, category, status, area, address, location_note, lat, lng, coords, phone, hours, summary, detail, cut_amount, cut_amount_note, effective_date, updated_at, action_label, action_url, alt_categories, source_title, source_url, retrieved, verified)
values
  ('svc-pavement', 'Street pavement maintenance', 'infrastructure', 'reduced', 'citywide', '42551 Osgood Rd, Fremont, CA 94539', 'City of Fremont Maintenance Center', 37.524862, -121.949177, 'census', '(510) 979-5700', null, 'About $3 million for pavement maintenance and for park and street-median capital replacement was removed from the General Fund to balance the FY 2025/26 budget.', 'The City Manager''s March 30, 2026 letter says the cut "was required to balance the budget" and that waiting to repair infrastructure raises later costs.', 3000000, 'Combined figure for pavement maintenance and park and street-median capital replacement.', '2025-07-01', '2026-03-30', 'Report a street problem to the City', 'https://www.fremont.gov/residents/report-issues', '{}'::text[], 'City Manager letter to Sen. Wahab and Asm. Lee, March 30, 2026', 'https://www.fremont.gov/home/showpublisheddocument/20676/639165034637630000', '2026-10-19', true),
  ('svc-park-median', 'Park and street-median capital replacement', 'parks', 'reduced', 'citywide', '3300 Capitol Ave, Building B, Fremont, CA 94538', 'Parks & Recreation offices, City Hall Building B', 37.551648, -121.983702, 'census', '(510) 494-4300', null, 'Capital replacement for parks and street medians was reduced as part of the same roughly $3 million General Fund cut that covered pavement maintenance.', 'The City''s February 13, 2026 release describes it as infrastructure maintenance spending reduced by approximately $3 million to balance the FY 2025/26 budget.', null, 'Included in the roughly $3 million listed under street pavement maintenance; the City does not publish a separate figure.', '2025-07-01', '2026-03-30', 'Report a park or median problem to the City', 'https://www.fremont.gov/residents/report-issues', '{}'::text[], 'City Manager letter to Sen. Wahab and Asm. Lee, March 30, 2026', 'https://www.fremont.gov/home/showpublisheddocument/20676/639165034637630000', '2026-10-19', true),
  ('svc-police-admin', 'Police Department administrative staffing', 'public_safety', 'reduced', '94538', '2000 Stevenson Blvd, Fremont, CA 94538', 'Fremont Police Department', 37.5497, -121.97, 'approximate', '(510) 790-6800', null, 'Six full-time administrative positions in the Police Department were eliminated in the February 10, 2026 budget rebalancing.', 'The City says no reductions were made to current sworn police positions, that positions were eliminated or reclassified, and that no layoffs were anticipated.', null, 'Part of the $3.8 million in operational reductions across all departments.', '2026-02-10', '2026-02-13', null, null, array['Referral']::text[], 'City Council Approves Budget Rebalancing (City of Fremont, Feb 13, 2026)', 'https://www.fremont.gov/Home/Components/News/News/1665/1067', '2026-10-19', true),
  ('svc-detention', 'Fremont Detention Facility staffing', 'public_safety', 'reduced', '94538', '1990 Stevenson Blvd, Fremont, CA 94538', 'Behind the Police Department building', 37.553059, -121.970074, 'census', '(510) 790-6800', null, 'Two detention officer positions and one detention supervisor position were eliminated in the February 10, 2026 budget rebalancing.', 'The City says the personnel reductions involve eliminating or reclassifying positions and that no layoffs were anticipated.', null, 'Part of the $3.8 million in operational reductions across all departments.', '2026-02-10', '2026-02-13', null, null, '{}'::text[], 'City Council Approves Budget Rebalancing (City of Fremont, Feb 13, 2026)', 'https://www.fremont.gov/Home/Components/News/News/1665/1067', '2026-10-19', true),
  ('svc-citywide-ops', 'Department operations: staffing, overtime, training and contract services', 'administration', 'reduced', 'citywide', '3300 Capitol Ave, Fremont, CA 94538', 'Fremont City Hall', 37.551648, -121.983702, 'census', '(510) 284-4000', null, 'Every City department reduced spending by its share of $3.8 million in new labor costs ($3.1 million of it in the General Fund). The reductions cover staffing, overtime, training and contract services.', 'The largest reductions were in Police, Fire and Maintenance Operations, which make up most of the General Fund. The City has not published which contract services or programs changed.', 3800000, 'Total for all departments; it includes the police and detention positions listed separately.', '2026-02-10', '2026-02-13', null, null, array['Referral']::text[], 'City Council Approves Budget Rebalancing (City of Fremont, Feb 13, 2026)', 'https://www.fremont.gov/Home/Components/News/News/1665/1067', '2026-10-19', true),
  ('svc-fire-ops', 'Fire Department operations budget', 'public_safety', 'reduced', 'citywide', '3300 Capitol Ave, Building A, Fremont, CA 94538', 'Fire Administration, City Hall Building A', 37.551648, -121.983702, 'census', '(510) 494-4200', null, 'Fire is one of the three departments with the largest reductions in the February 2026 rebalancing. No reductions were made to current sworn fire positions.', 'A March 30, 2026 City letter adds that one more fire company recommended by the department''s Standards of Coverage report is not funded.', null, 'Part of the $3.8 million in operational reductions across all departments.', '2026-02-10', '2026-03-30', null, null, '{}'::text[], 'City Council Approves Budget Rebalancing (City of Fremont, Feb 13, 2026)', 'https://www.fremont.gov/Home/Components/News/News/1665/1067', '2026-10-19', true),
  ('svc-human-services', 'Human Services safety-net programs', 'human_services', 'reduced', '94538', '3300 Capitol Ave, Building B, Fremont, CA 94538', 'Human Services Department, City Hall Building B', 37.551648, -121.983702, 'census', '(510) 574-2050', 'Mon–Fri 8:30 am–5:00 pm; closed 12:00–1:00 pm', 'The City says State and federal funding changes will require eliminating 10 more positions in the Human Services Department, which provides safety-net services.', 'Separately, the FY 2026/27 Proposed Budget shows Human Services staffing going from 82.7 to 79.9 full-time-equivalent positions (a change of 2.8, in funds other than the General Fund). The City has not said which programs are affected.', null, 'The City has not published a dollar figure.', null, '2026-05-12', null, null, array['Food', 'Housing', 'Health', 'Seniors', 'Referral']::text[], 'City Manager letter to Sen. Wahab and Asm. Lee, March 30, 2026', 'https://www.fremont.gov/home/showpublisheddocument/20676/639165034637630000', '2026-10-19', true),
  ('svc-homeless-response', 'Homelessness response services', 'human_services', 'open', 'citywide', '3300 Capitol Ave, Building B, Fremont, CA 94538', 'Human Services Department, City Hall Building B', 37.551648, -121.983702, 'census', '(510) 574-2050', null, 'The FY 2025/26 budget kept funding the existing level of homelessness services, about $8 million, and moved $667,000 among programs.', 'That included $150,000 more for Keep Fremont Housed and $128,000 in new funding for overdose prevention and substance use services. This is the status as of the City Manager''s message after the June 10, 2025 adoption; we found no later change in the sources checked.', null, null, '2025-07-01', '2025-06-10', null, null, array['Housing', 'Food', 'Referral']::text[], 'Community Message from the City Manager on the FY 2025/26 Operating Budget', 'https://www.fremont.gov/home/showpublisheddocument/18479/638868997000130000', '2026-10-19', true),
  ('svc-age-well-lake', 'Age Well Center at Lake Elizabeth', 'seniors', 'open', '94538', '40086 Paseo Padre Pkwy, Fremont, CA 94538', null, 37.54579, -121.966306, 'census', '(510) 790-6600', 'Mon–Fri 8:00 am–4:30 pm, except City holidays', 'Classes, meals and services for adults 55 and older. Listed as open with regular hours on the City''s Aging and Family Services page.', 'We found no budget-related change for this center in the City sources checked. Call to confirm before visiting.', null, null, null, '2026-10-12', null, null, array['Seniors']::text[], 'Aging and Family Services (City of Fremont)', 'https://www.fremont.gov/residents/older-adults-caregivers', '2026-10-19', true),
  ('svc-age-well-south', 'Age Well Center at South Fremont', 'seniors', 'open', '94539', '47111 Mission Falls Ct, Fremont, CA 94539', null, 37.485181, -121.928984, 'census', '(510) 742-7540', 'Mon–Fri 8:00 am–4:30 pm, except City holidays', 'Classes, meals and services for adults 55 and older. Listed as open with regular hours on the City''s Aging and Family Services page.', 'We found no budget-related change for this center in the City sources checked. Call to confirm before visiting.', null, null, null, '2026-10-12', null, null, array['Seniors']::text[], 'Aging and Family Services (City of Fremont)', 'https://www.fremont.gov/residents/older-adults-caregivers', '2026-10-19', true),
  ('svc-youth-family', 'Youth and Family Services counseling', 'youth', 'open', '94538', '39155 Liberty St, Suite E500, Fremont, CA 94538', 'Inside the Fremont Family Resource Center', 37.5522, -121.9765, 'approximate', '(510) 574-2100', 'Mon–Fri 8:00 am–5:00 pm', 'Individual and family counseling for Fremont youth and families, with fees on a sliding scale. Listed as open on the City''s Youth and Family Services page.', 'The City lists counseling in Spanish, Farsi, Mandarin, Urdu, Marathi and Hebrew and notes that language capacity can change. We found no budget-related change for this program in the City sources checked.', null, null, null, '2026-10-12', null, null, array['Health', 'Referral']::text[], 'Youth & Family Services (City of Fremont)', 'https://www.fremont.gov/residents/youth', '2026-10-19', true),
