insert into public.resources
  (id, name, category, area, address, lat, lng, coords, phone, website, hours, description, languages, language_note, source_url, retrieved, verified)
values
  ('res-tcv', 'TCV Food Bank + Mobile Pantry', 'Food', '94536', '37350 Joseph St, Fremont, CA 94536', 37.555687, -122.007758, 'census', '(510) 793-4583', 'https://tcvfoodbank.org/', 'Marketplace: Mon–Thu 10:00 am–2:00 pm; Fri 10:00–11:30 am (drive-thru only)', 'Free groceries for Alameda County residents who meet income requirements. First-time shoppers bring an ID to sign up for a TCV card; new cards are not issued on Fridays. Mobile pantry sites are listed on the website.', '{}'::text[], 'Website available in English, Spanish, Chinese, Farsi and Vietnamese.', 'https://tcvfoodbank.org/', '2026-10-19', true),
  ('res-211', '211 Alameda County', 'Referral', 'citywide', 'Phone and online service', null, null, null, '211', 'https://211alamedacounty.org/', '24 hours a day, 7 days a week', 'Free, confidential help from a person who can refer you to food, housing, health and other services in Alameda County.', '{}'::text[], 'Ask about language help when you call.', 'https://211alamedacounty.org/', '2026-10-19', true),
  ('res-frc', 'Fremont Family Resource Center', 'Referral', '94538', '39155 Liberty St, Fremont, CA 94538', 37.5522, -121.9765, 'approximate', '(510) 574-2021', 'https://www.fremont.gov/government/departments/human-services', null, 'A City-run center that houses City, County and nonprofit agencies in one place. Call to ask which agency can help and whether it takes walk-ins.', '{}'::text[], null, 'https://www.fremont.gov/about/resource-directory/-selcat-83-1526', '2026-10-19', true),
  ('res-senior-infoline', 'City of Fremont Senior InfoLine', 'Seniors', 'citywide', '3300 Capitol Ave, Building B, Fremont, CA 94538', 37.551648, -121.983702, 'census', '(510) 574-2041', 'https://www.fremont.gov/residents/older-adults-caregivers', 'Office Mon–Fri 8:30 am–5:00 pm; closed 12:00–1:00 pm', 'Resources and help for older adults and caregivers, including benefits questions. Leave a message and the City says calls are returned within 2 days.', array['English', 'Spanish', 'Farsi', 'Mandarin']::text[], null, 'https://www.fremont.gov/residents/older-adults-caregivers', '2026-10-19', true),
  ('res-bach-liberty', 'Bay Area Community Health: Liberty Clinic', 'Health', '94538', '39500 Liberty St, Fremont, CA 94538', 37.5489, -121.9759, 'approximate', '(510) 770-8040', 'https://bach.health/alameda-county-locations', 'Mon–Thu 8:00 am–7:00 pm; Fri–Sat 8:00 am–5:00 pm', 'Community health center with medical, behavioral health and vision care, plus help with health insurance. The phone number is the appointment line for all Bay Area Community Health clinics.', '{}'::text[], null, 'https://bach.health/alameda-county-locations', '2026-10-19', true),
  ('res-bach-irvington', 'Bay Area Community Health: Irvington Dave Clinic', 'Health', '94538', '40910 Fremont Blvd, Fremont, CA 94538', 37.533997, -121.960797, 'census', '(510) 770-8040', 'https://bach.health/alameda-county-locations', 'Medical: Mon–Fri 8:00 am–7:00 pm, Sun 8:00 am–5:00 pm. Dental: Mon–Fri 8:00 am–7:00 pm, Sat 8:00 am–5:00 pm', 'Medical, pediatric, behavioral health and dental care, plus help with health insurance. Call the appointment line first.', '{}'::text[], null, 'https://bach.health/alameda-county-locations', '2026-10-19', true),
  ('res-bach-mowry', 'Bay Area Community Health: Mowry II Clinic', 'Health', '94538', '1999 Mowry Ave, Fremont, CA 94538', 37.558112, -121.980813, 'census', '(510) 770-8040', 'https://bach.health/alameda-county-locations', 'Medical: Mon–Fri 8:00 am–5:00 pm. Teen Clinic: Mon–Thu 9:00 am–6:00 pm, Fri 8:00 am–5:00 pm. Convenient Care: Mon–Fri 5:00–8:00 pm', 'Medical and behavioral health care with a Teen Clinic and Women''s Health. Several suites share this address; ask which one when you call.', '{}'::text[], null, 'https://bach.health/alameda-county-locations', '2026-10-19', true),
  ('res-988', '988 Suicide & Crisis Lifeline', 'Crisis', 'citywide', 'Phone service', null, null, null, '988', 'https://988lifeline.org/', '24 hours a day, 7 days a week', 'Trained crisis counselors by phone at any hour. The City''s Youth and Family Services page points residents to this line. For a life-threatening emergency call 911.', '{}'::text[], null, 'https://www.fremont.gov/residents/youth', '2026-10-19', true),
  ('res-abode', 'Abode Services', 'Housing', '94538', '40849 Fremont Blvd, Fremont, CA 94538', 37.534291, -121.961838, 'census', '(510) 657-7409', 'https://abode.org/', null, 'Nonprofit that provides housing and support services for people experiencing homelessness. This is the administrative office; call to ask how to get help.', '{}'::text[], null, 'https://abode.org/', '2026-10-19', true),
  ('res-iiba', 'Immigration Institute of the Bay Area: Fremont', 'Legal', '94538', '39055 Hastings St, Suite 202, Fremont, CA 94538', 37.552819, -121.984194, 'census', '(510) 894-3639', 'https://iibayarea.org/offices/fremont/', null, 'Nonprofit immigration legal services and workshops for Alameda County. First consultations are booked by phone or online.', '{}'::text[], 'The website and booking instructions are also in Spanish.', 'https://iibayarea.org/offices/fremont/', '2026-10-19', true),
  ('res-lov', 'League of Volunteers (LOV)', 'Community', 'citywide', 'PO Box 1170, Newark, CA 94560 (no walk-in office)', null, null, null, '(510) 793-5683', 'https://www.lov.org/contact-lov', 'Tue–Fri 9:00 am–2:00 pm', 'Tri-City nonprofit that runs holiday food and toy drives, Adopt-A-Family, summer recreation and community events. The staff work remotely, so call or email first.', '{}'::text[], null, 'https://www.lov.org/contact-lov', '2026-10-19', true),
  ('res-library-fremont', 'Fremont Library', 'Library', '94538', '2400 Stevenson Blvd, Fremont, CA 94538', 37.552842, -121.970537, 'census', '(510) 745-1400', 'https://aclibrary.org/locations/', null, 'Alameda County Library branch. It is run by the County, not paid for from the City of Fremont budget. Hours differ by day; check the website or call.', '{}'::text[], null, 'https://aclibrary.org/locations/', '2026-10-19', true),
  ('res-library-centerville', 'Centerville Library', 'Library', '94536', '3801 Nicolet Ave, Fremont, CA 94536', 37.567809, -122.021342, 'census', '(510) 795-2629', 'https://aclibrary.org/locations/', null, 'Alameda County Library branch. It is run by the County, not paid for from the City of Fremont budget. Hours differ by day; check the website or call.', '{}'::text[], null, 'https://aclibrary.org/locations/', '2026-10-19', true),
  ('res-library-niles', 'Niles Library', 'Library', '94536', '150 I St, Fremont, CA 94536', 37.576466, -121.978071, 'census', '(510) 795-2626', 'https://aclibrary.org/locations/', null, 'Alameda County Library branch. It is run by the County, not paid for from the City of Fremont budget. Hours differ by day; check the website or call.', '{}'::text[], null, 'https://aclibrary.org/locations/', '2026-10-19', true),
  ('res-alameda-county-assessor-s-office-2fb4c37', 'Alameda County Assessor''s Office', 'Referral', 'citywide', '1221 Oak St. Room 145 Oakland, CA 94612', null, null, null, '(510) 272-3787', 'http://www.acgov.org/assessor/', null, 'The City of Fremont lists this provider under its Alameda County Offices category. Contact the provider to confirm current services, hours, and eligibility.', '{}'::text[], null, 'https://www.fremont.gov/about/resource-directory/-selcat-73-1526', '2026-10-19', true),
